  Lemma pxd_B1 : forall regs m (data : Z),
    (1 <= data)%Z -> (data < 2 ^ 64)%Z ->
    rdn SEGS m (Z_to_bv 64 0x394f8) 8 = Some (Z_to_le_bytes 8 0x2f80c) ->
    getr regs 10 = Z_to_bv 64 data ->
    exists regs',
      msteps SEGS (mkst regs (0x19460 : word) m rom) (mkst regs' (0x2f80c : word) m rom)
      /\ getr regs' 10 = Z_to_bv 64 data /\ getr regs' 1 = Z_to_bv 64 0x19470
      /\ regs_agree (fun r => In r [1; 11]%list) regs regs'.
Proof.
