  (* [comment removed for export] *)
  Lemma pxd_C2 : forall regs m (pix : Z),
    (0 <= pix)%Z -> (pix + 64 < 2 ^ 64)%Z ->
    store_ok SEGS m (Z_to_bv 64 pix) 64 = true ->
    getr regs 8 = Z_to_bv 64 pix ->
    msteps SEGS (mkst regs (0x19490 : word) m rom)
                (mkst regs (0x19494 : word) (wbytes m (Z_to_bv 64 (pix + 48)) (word_to_le_bytes 8 (Z_to_bv 64 0))) rom).
Proof.
